import React, { useEffect, useMemo, useRef, useState } from "react";
import {
  Platform,
  AccessibilityInfo,
  PanResponder,
  StyleSheet,
  View,
  type ViewStyle,
} from "react-native";
import {
  Canvas,
  Group,
  ImageShader,
  Vertices,
  makeImageFromView,
  type SkImage,
} from "@shopify/react-native-skia";
import {
  cancelAnimation,
  Easing,
  runOnJS,
  useDerivedValue,
  useSharedValue,
  withTiming,
} from "react-native-reanimated";
import {
  makeGrid,
  meshPoints,
  releaseTarget,
  scrub,
  type Point,
  type Rect,
} from "./genieMath";
export type GenieDismissProps = {
  image: SkImage;
  width: number;
  height: number;
  card: Rect;
  target: Point;
  minimized: boolean;
  onMinimizedChange: (minimized: boolean) => void;
  slowMotion?: boolean;
  reducedMotion?: boolean;
  label?: string;
  style?: ViewStyle;
};
// Native-only helper. Capture after layout/fonts/images are ready, with collapsable={false}.
// The owner disposes the returned image AFTER the component using it unmounts.
// Web callers should supply a prepared SkImage instead; this helper is not a DOM capture tool.
export async function snapshotCard(
  ref: React.RefObject<View | null>,
): Promise<SkImage> {
  if (Platform.OS === "web")
    throw new Error(
      "snapshotCard is native-only; provide a prepared SkImage on web",
    );
  if (!ref.current) throw new Error("Card view is not mounted");
  const image = await makeImageFromView(ref);
  if (!image) throw new Error("Unable to capture card");
  return image;
}
export function GenieDismiss({
  image,
  width,
  height,
  card,
  target,
  minimized,
  onMinimizedChange,
  slowMotion = false,
  reducedMotion,
  label = "Minimizable card",
  style,
}: GenieDismissProps) {
  const progress = useSharedValue(minimized ? 1 : 0);
  const [systemReduce, setSystemReduce] = useState(false);
  const reduce = !!reducedMotion || systemReduce;
  const grid = useMemo(() => makeGrid(), []);
  const textures = useMemo(
    () =>
      grid.uv.map((p) => ({ x: p.x * image.width(), y: p.y * image.height() })),
    [grid, image],
  );
  const destination = useRef(minimized),
    pendingNotify = useRef(false);
  const mounted = useRef(true),
    dragging = useRef(false),
    start = useRef(0);
  const latest = useRef({
    minimized,
    slowMotion,
    reduce,
    card,
    onMinimizedChange,
  });
  latest.current = { minimized, slowMotion, reduce, card, onMinimizedChange };
  useEffect(() => {
    mounted.current = true;
    AccessibilityInfo.isReduceMotionEnabled()
      .then((v) => {
        if (mounted.current) setSystemReduce(v);
      })
      .catch(() => {});
    const sub = AccessibilityInfo.addEventListener(
      "reduceMotionChanged",
      setSystemReduce,
    );
    return () => {
      mounted.current = false;
      sub.remove();
      cancelAnimation(progress);
    };
  }, [progress]);
  const commit = (value: boolean) => {
    if (mounted.current) latest.current.onMinimizedChange(value);
  };
  const settle = (value: boolean, notify = false) => {
    destination.current = value;
    pendingNotify.current = notify;
    cancelAnimation(progress);
    const l = latest.current,
      end = value ? 1 : 0;
    progress.value = withTiming(
      end,
      {
        duration: l.reduce
          ? 140
          : Math.max(
              120,
              Math.abs(end - progress.value) * (l.slowMotion ? 3600 : 900),
            ),
        easing: Easing.inOut(Easing.cubic),
      },
      (done) => {
        if (done && notify) runOnJS(commit)(value);
      },
    );
  };
  useEffect(() => {
    dragging.current = false;
    settle(minimized);
  }, [minimized]);
  useEffect(() => {
    if (!dragging.current) settle(destination.current, pendingNotify.current);
  }, [slowMotion, reduce]);
  // New content/layout cancels stale gestures and uses the current controlled endpoint.
  useEffect(() => {
    dragging.current = false;
    destination.current = minimized;
    pendingNotify.current = false;
    cancelAnimation(progress);
    progress.value = minimized ? 1 : 0;
  }, [
    image,
    width,
    height,
    card.x,
    card.y,
    card.width,
    card.height,
    target.x,
    target.y,
  ]);
  const responder = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: (e) => e.nativeEvent.touches.length === 1,
        onPanResponderGrant: () => {
          cancelAnimation(progress);
          dragging.current = true;
          start.current = progress.value;
        },
        onPanResponderMove: (_, g) => {
          progress.value = scrub(
            start.current,
            g.dy,
            latest.current.card.height,
          );
        },
        onPanResponderRelease: (_, g) => {
          dragging.current = false;
          const next =
            Math.abs(g.dy) < 4
              ? !destination.current
              : releaseTarget(progress.value, g.vy);
          settle(next, true);
        },
        onPanResponderTerminate: () => {
          dragging.current = false;
          settle(latest.current.minimized);
        },
        onPanResponderTerminationRequest: () => true,
      }),
    [progress],
  );
  const vertices = useDerivedValue(() =>
    meshPoints(grid.uv, reduce ? 0 : progress.value, card, target),
  );
  const opacity = useDerivedValue(() => (reduce ? 1 - progress.value : 1));
  if (width <= 0 || height <= 0 || card.width <= 0 || card.height <= 0)
    return null;
  return (
    <View
      style={[{ width, height }, style]}
      {...responder.panHandlers}
      accessible
      accessibilityRole="button"
      accessibilityLabel={label}
      accessibilityValue={{ text: minimized ? "Minimized" : "Open" }}
      accessibilityActions={[
        {
          name: "activate",
          label: minimized ? "Restore card" : "Minimize card",
        },
      ]}
      onAccessibilityAction={() => settle(!destination.current, true)}
    >
      <Canvas pointerEvents="none" style={StyleSheet.absoluteFill}>
        <Group opacity={opacity}>
          <Vertices
            vertices={vertices}
            textures={textures}
            indices={grid.indices}
            mode="triangles"
            blendMode="srcOver"
          >
            <ImageShader image={image} tx="clamp" ty="clamp" />
          </Vertices>
        </Group>
      </Canvas>
    </View>
  );
}

export type Point = { x: number; y: number };
export type Rect = Point & { width: number; height: number };
export const clamp = (v: number) => {
  "worklet";
  return Math.max(0, Math.min(1, v));
};
const smooth = (v: number) => {
  "worklet";
  const t = clamp(v);
  return t * t * (3 - 2 * t);
};
export function makeGrid(columns = 12, rows = 24) {
  const uv: Point[] = [],
    indices: number[] = [];
  for (let y = 0; y <= rows; y++)
    for (let x = 0; x <= columns; x++) uv.push({ x: x / columns, y: y / rows });
  for (let y = 0; y < rows; y++)
    for (let x = 0; x < columns; x++) {
      const a = y * (columns + 1) + x,
        b = a + 1,
        c = a + columns + 1,
        d = c + 1;
      indices.push(a, b, c, b, d, c);
    }
  return { uv, indices };
}
// A bottom-first narrowing wave, followed by transport down the funnel.
// Texture coordinates never change. The two endpoints are exact.
export function warpPoint(
  uv: Point,
  progress: number,
  card: Rect,
  target: Point,
): Point {
  "worklet";
  const p = clamp(progress),
    v = uv.y;
  if (p === 0)
    return { x: card.x + uv.x * card.width, y: card.y + v * card.height };
  if (p === 1) return { x: target.x, y: target.y };
  const transport = smooth((p - 0.28) / 0.72);
  const wave = smooth((p * 1.55 - (1 - v) * 0.52) / 0.72);
  const center = card.x + card.width / 2;
  const bend = wave * (1 - transport);
  const rowCenter = center + (target.x - center) * (bend + transport);
  const width = card.width * (1 - wave * 0.92) * (1 - transport);
  return {
    x: rowCenter + (uv.x - 0.5) * width,
    y: (card.y + v * card.height) * (1 - transport) + target.y * transport,
  };
}
export function meshPoints(uv: Point[], p: number, card: Rect, target: Point) {
  "worklet";
  return uv.map((point) => warpPoint(point, p, card, target));
}
export function releaseTarget(p: number, velocityY: number) {
  "worklet";
  return Math.abs(velocityY) > 0.35 ? velocityY > 0 : p >= 0.5;
}
export function scrub(start: number, dy: number, distance: number) {
  "worklet";
  return clamp(start + dy / Math.max(1, distance));
}

import React, { useEffect, useMemo, useState } from "react";
import { Pressable, Text, View } from "react-native";
import { Skia } from "@shopify/react-native-skia";
import { GenieDismiss } from "./GenieDismiss";
const card = { x: 24, y: 20, width: 272, height: 280 };
export default function Example() {
  const [minimized, setMinimized] = useState(false),
    [slow, setSlow] = useState(false),
    [left, setLeft] = useState(false);
  const target = { x: left ? 50 : 270, y: 365 };
  const image = useMemo(() => {
    const surface = Skia.Surface.MakeOffscreen(544, 560);
    if (!surface) throw new Error("Unable to prepare card texture");
    const c = surface.getCanvas(),
      paint = Skia.Paint();
    c.clear(Skia.Color("#e9e6db"));
    paint.setColor(Skia.Color("#315843"));
    c.drawRect(Skia.XYWHRect(36, 40, 210, 12), paint);
    c.drawRect(Skia.XYWHRect(36, 80, 350, 24), paint);
    paint.setColor(Skia.Color("#ae8655"));
    c.drawCircle(340, 290, 150, paint);
    paint.setColor(Skia.Color("#315843"));
    c.drawCircle(195, 350, 110, paint);
    paint.setColor(Skia.Color("#b7c7a0"));
    c.drawCircle(385, 340, 80, paint);
    paint.setColor(Skia.Color("#315843"));
    c.drawRect(Skia.XYWHRect(36, 505, 160, 10), paint);
    surface.flush();
    const snapshot = surface.makeImageSnapshot(),
      copy = snapshot.makeNonTextureImage();
    snapshot.dispose();
    surface.dispose();
    paint.dispose();
    if (!copy) throw new Error("Unable to copy card texture");
    return copy;
  }, []);
  useEffect(() => () => image.dispose(), [image]);
  return (
    <View style={{ alignItems: "center", gap: 12 }}>
      <View>
        <View
          style={{
            position: "absolute",
            left: target.x - 22,
            top: target.y - 22,
            width: 44,
            height: 44,
            borderRadius: 22,
            backgroundColor: "#315843",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          <Text style={{ color: "#fff" }}>↓</Text>
        </View>
        <GenieDismiss
          image={image}
          width={320}
          height={410}
          card={card}
          target={target}
          minimized={minimized}
          onMinimizedChange={setMinimized}
          slowMotion={slow}
        />
      </View>
      <Pressable
        accessibilityRole="button"
        onPress={() => setMinimized((v) => !v)}
        style={{ padding: 12, backgroundColor: "#315843", borderRadius: 24 }}
      >
        <Text style={{ color: "#fff" }}>
          {minimized ? "Restore card" : "Minimize card"}
        </Text>
      </Pressable>
      <View style={{ flexDirection: "row", gap: 12 }}>
        <Pressable
          accessibilityRole="switch"
          accessibilityState={{ checked: slow }}
          onPress={() => setSlow((v) => !v)}
          style={{ padding: 10 }}
        >
          <Text>Slow motion: {slow ? "on" : "off"}</Text>
        </Pressable>
        <Pressable
          accessibilityRole="button"
          onPress={() => {
            setMinimized(false);
            setLeft((v) => !v);
          }}
          style={{ padding: 10 }}
        >
          <Text>Target: {left ? "left" : "right"}</Text>
        </Pressable>
      </View>
      <Text style={{ fontSize: 12, color: "#63705f" }}>
        Drag down to tuck away. Drag up to bring it back.
      </Text>
    </View>
  );
}
